# Lesson 3.1: Intro to HTML and the HTML skeleton (taught: DOCTYPE, html, head, title, body, h1, h2, p; closing tags; comments)
L = lambda *a: '\n'.join(a)
def P(title, story, code, dis): return (title, story, code, dis)
